import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"📘 申论","description":"","frontmatter":{},"headers":[],"relativePath":"shenlun/index.md","filePath":"shenlun/index.md"}'),o={name:"shenlun/index.md"};function d(i,a,h,n,u,s){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="📘-申论" tabindex="-1">📘 申论 <a class="header-anchor" href="#📘-申论" aria-label="Permalink to &quot;📘 申论&quot;">​</a></h1><p>申论考察文字表达、分析问题和解决问题的能力。和行测不同，申论没有标准答案，但有<strong>高分规律</strong>。</p><h2 id="⏱-考试概况" tabindex="-1">⏱ 考试概况 <a class="header-anchor" href="#⏱-考试概况" aria-label="Permalink to &quot;⏱ 考试概况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>国考</th><th>省考</th></tr></thead><tbody><tr><td>时间</td><td>180 分钟</td><td>150 分钟</td></tr><tr><td>题量</td><td>5 题</td><td>4 题</td></tr><tr><td>字数</td><td>约 2000-2500 字</td><td>约 1800-2000 字</td></tr></tbody></table><h2 id="📐-五大题型" tabindex="-1">📐 五大题型 <a class="header-anchor" href="#📐-五大题型" aria-label="Permalink to &quot;📐 五大题型&quot;">​</a></h2><h3 id="概括归纳-←-基础中的基础" tabindex="-1"><a href="./gaikuo-guina">概括归纳</a> ← 基础中的基础 <a class="header-anchor" href="#概括归纳-←-基础中的基础" aria-label="Permalink to &quot;[概括归纳](./gaikuo-guina) ← 基础中的基础&quot;">​</a></h3><ul><li>从材料中提取要点，归纳整理</li><li><strong>核心原则</strong>：所有答案都在材料里！</li></ul><h3 id="综合分析-←-理解深度" tabindex="-1"><a href="./zonghe-fenxi">综合分析</a> ← 理解深度 <a class="header-anchor" href="#综合分析-←-理解深度" aria-label="Permalink to &quot;[综合分析](./zonghe-fenxi) ← 理解深度&quot;">​</a></h3><ul><li>分析现象原因、影响、本质</li><li>常见：词句理解题、观点分析题</li></ul><h3 id="对策建议-←-解决问题" tabindex="-1"><a href="./duice-jianyi">对策建议</a> ← 解决问题 <a class="header-anchor" href="#对策建议-←-解决问题" aria-label="Permalink to &quot;[对策建议](./duice-jianyi) ← 解决问题&quot;">​</a></h3><ul><li>针对问题提出具体可行的建议</li><li><strong>注意</strong>：对策要有针对性、可行性</li></ul><h3 id="公文写作-←-格式规范" tabindex="-1"><a href="./gongwen-xiezuo">公文写作</a> ← 格式规范 <a class="header-anchor" href="#公文写作-←-格式规范" aria-label="Permalink to &quot;[公文写作](./gongwen-xiezuo) ← 格式规范&quot;">​</a></h3><ul><li>通知、报告、倡议书、讲话稿等</li><li><strong>关键</strong>：格式正确 + 内容充实</li></ul><h3 id="大作文-←-综合能力" tabindex="-1"><a href="./dazuowen">大作文</a> ← 综合能力 <a class="header-anchor" href="#大作文-←-综合能力" aria-label="Permalink to &quot;[大作文](./dazuowen) ← 综合能力&quot;">​</a></h3><ul><li>1000-1200 字的议论文</li><li>总分总结构 + 论证有力 + 语言规范</li></ul><hr><h2 id="🎯-申论高分心法" tabindex="-1">🎯 申论高分心法 <a class="header-anchor" href="#🎯-申论高分心法" aria-label="Permalink to &quot;🎯 申论高分心法&quot;">​</a></h2><h3 id="_1-材料为王" tabindex="-1">1. 材料为王 <a class="header-anchor" href="#_1-材料为王" aria-label="Permalink to &quot;1. 材料为王&quot;">​</a></h3><blockquote><p>一切答案来源于材料，不要自创！不要自创！不要自创！</p></blockquote><h3 id="_2-要点全面" tabindex="-1">2. 要点全面 <a class="header-anchor" href="#_2-要点全面" aria-label="Permalink to &quot;2. 要点全面&quot;">​</a></h3><blockquote><p>阅卷按点给分，宁可多写不相关的，不能漏掉材料里的要点</p></blockquote><h3 id="_3-归纳提炼" tabindex="-1">3. 归纳提炼 <a class="header-anchor" href="#_3-归纳提炼" aria-label="Permalink to &quot;3. 归纳提炼&quot;">​</a></h3><blockquote><p>不直接抄原材料句子，用自己的话概括（但要保留原意）</p></blockquote><h3 id="_4-结构清晰" tabindex="-1">4. 结构清晰 <a class="header-anchor" href="#_4-结构清晰" aria-label="Permalink to &quot;4. 结构清晰&quot;">​</a></h3><blockquote><p>每条答案：<strong>总括句 + 具体要点</strong> 答卷布局：<strong>总 → 分 → 总</strong></p></blockquote><h3 id="_5-字迹工整" tabindex="-1">5. 字迹工整 <a class="header-anchor" href="#_5-字迹工整" aria-label="Permalink to &quot;5. 字迹工整&quot;">​</a></h3><blockquote><p>阅卷老师 30 秒看一道小题，字迹是第一印象</p></blockquote><hr><h2 id="📝-每日积累计划" tabindex="-1">📝 每日积累计划 <a class="header-anchor" href="#📝-每日积累计划" aria-label="Permalink to &quot;📝 每日积累计划&quot;">​</a></h2><ul><li>[ ] 每天读一篇人民日报评论</li><li>[ ] 积累 3 个好词好句</li><li>[ ] 每周写一篇完整的大作文</li></ul><hr><h2 id="📊-各题型掌握情况" tabindex="-1">📊 各题型掌握情况 <a class="header-anchor" href="#📊-各题型掌握情况" aria-label="Permalink to &quot;📊 各题型掌握情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题型</th><th>水平</th><th>薄弱点</th></tr></thead><tbody><tr><td>概括归纳</td><td>⭐⭐⭐☆☆</td><td>有时候归纳不够精炼</td></tr><tr><td>综合分析</td><td>⭐⭐☆☆☆</td><td>分析深度不够</td></tr><tr><td>对策建议</td><td>⭐⭐☆☆☆</td><td>对策太泛，不够具体</td></tr><tr><td>公文写作</td><td>⭐⭐⭐☆☆</td><td>格式需要巩固</td></tr><tr><td>大作文</td><td>⭐⭐☆☆☆</td><td>论证不够充分</td></tr></tbody></table>',33)])])}const q=t(o,[["render",d]]);export{b as __pageData,q as default};
